Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class TeachingUI {
 [DllImport("user32.dll",CharSet=CharSet.Unicode,EntryPoint="SendMessageW")] static extern IntPtr SendText(IntPtr h,uint m,IntPtr wp,string s);
 [DllImport("user32.dll")] static extern IntPtr GetDC(IntPtr h);
 [DllImport("user32.dll")] static extern int ReleaseDC(IntPtr h,IntPtr dc);
 [DllImport("gdi32.dll")] static extern uint GetPixel(IntPtr dc,int x,int y);
 public static int FindList(IntPtr h,string text){return SendText(h,0x1A2,(IntPtr)(-1),text).ToInt32();}
 public static int[] PointA(IntPtr view){IntPtr dc=GetDC(view);long xsum=0,ysum=0;int n=0;try{for(int y=125;y<520;y++)for(int x=135;x<620;x++){if(GetPixel(dc,x,y)==0xAF5F19){xsum+=x;ysum+=y;n++;}}}finally{ReleaseDC(view,dc);}if(n<15)throw new Exception("Graph point A is not painted");return new[]{(int)(xsum/n),(int)(ysum/n),n};}
}
'@
Add-Type @'
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class PairGridUI {
 [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h,out uint id);
 [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(uint access,bool inherit,uint id);
 [DllImport("kernel32.dll")] static extern IntPtr VirtualAllocEx(IntPtr process,IntPtr address,UIntPtr bytes,uint type,uint protect);
 [DllImport("kernel32.dll")] static extern bool VirtualFreeEx(IntPtr process,IntPtr address,UIntPtr bytes,uint type);
 [DllImport("kernel32.dll")] static extern bool WriteProcessMemory(IntPtr process,IntPtr address,byte[] data,UIntPtr bytes,out UIntPtr written);
 [DllImport("kernel32.dll")] static extern bool ReadProcessMemory(IntPtr process,IntPtr address,byte[] data,UIntPtr bytes,out UIntPtr read);
 [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
 [DllImport("user32.dll")] static extern IntPtr SendMessageTimeout(IntPtr h,uint message,IntPtr wp,IntPtr lp,uint flags,uint ms,out UIntPtr result);
 [DllImport("user32.dll")] static extern bool OpenClipboard(IntPtr owner);
 [DllImport("user32.dll")] static extern bool EmptyClipboard();
 [DllImport("user32.dll")] static extern IntPtr SetClipboardData(uint format,IntPtr data);
 [DllImport("user32.dll")] static extern bool CloseClipboard();
 [DllImport("kernel32.dll")] static extern IntPtr GlobalAlloc(uint flags,UIntPtr bytes);
 [DllImport("kernel32.dll")] static extern IntPtr GlobalLock(IntPtr h);
 [DllImport("kernel32.dll")] static extern bool GlobalUnlock(IntPtr h);
 [DllImport("kernel32.dll")] static extern IntPtr GlobalFree(IntPtr h);
 public static int[] Cell(IntPtr grid,int row,int column){uint id;GetWindowThreadProcessId(grid,out id);IntPtr process=OpenProcess(0x438,false,id),memory=VirtualAllocEx(process,IntPtr.Zero,(UIntPtr)16,0x3000,4);try{if(process==IntPtr.Zero||memory==IntPtr.Zero)throw new Exception("List-view access failed");byte[] data=new byte[16];Array.Copy(BitConverter.GetBytes(column+1),0,data,4,4);UIntPtr count,result;if(!WriteProcessMemory(process,memory,data,(UIntPtr)16,out count)||SendMessageTimeout(grid,0x1038,(IntPtr)row,memory,2,5000,out result)==IntPtr.Zero||result==UIntPtr.Zero||!ReadProcessMemory(process,memory,data,(UIntPtr)16,out count))throw new Exception("List-view cell bounds unavailable");return new[]{BitConverter.ToInt32(data,0)+8,(BitConverter.ToInt32(data,4)+BitConverter.ToInt32(data,12))/2};}finally{if(memory!=IntPtr.Zero)VirtualFreeEx(process,memory,UIntPtr.Zero,0x8000);if(process!=IntPtr.Zero)CloseHandle(process);}}
 public static void Clipboard(string text){byte[] data=Encoding.Unicode.GetBytes(text+"\0");IntPtr h=GlobalAlloc(2,(UIntPtr)data.Length);if(h==IntPtr.Zero)throw new Exception("Clipboard allocation failed");bool owned=true;try{IntPtr p=GlobalLock(h);Marshal.Copy(data,0,p,data.Length);GlobalUnlock(h);if(!OpenClipboard(IntPtr.Zero))throw new Exception("Clipboard unavailable");try{EmptyClipboard();if(SetClipboardData(13,h)==IntPtr.Zero)throw new Exception("Clipboard data failed");owned=false;}finally{CloseClipboard();}}finally{if(owned)GlobalFree(h);}}
}
