 $bar=[MathomirUiProbe]::Child($main,1110);$br=[MathomirUiProbe]::WindowRect($bar);$vr=[MathomirUiProbe]::WindowRect($view);Check ($vr.Top -ge $br.Bottom) 'Toolbar overlaps the editable page';$rects=@()
